using System;
using Volo.Abp;
using Volo.Abp.Domain.Entities;
namespace ShikshaMitra.Students.StudentEnrollments.Admissions;
public class AdmissionFormFieldDefinition : Entity<Guid>
{
	public Guid FormDefinitionId { get; private set; } public Guid SectionId { get; private set; } public string Code { get; private set; } public string Label { get; private set; } public AdmissionFormFieldType FieldType { get; private set; } public AdmissionFormBindingType BindingType { get; private set; } public string? BindingKey { get; private set; } public string? Placeholder { get; private set; } public string? HelpText { get; private set; } public string? DefaultValue { get; private set; } public bool Required { get; private set; } public bool ReadOnly { get; private set; } public int DisplayOrder { get; private set; } public string? ValidationJson { get; private set; } public string? VisibilityRuleJson { get; private set; }
	protected AdmissionFormFieldDefinition() { }
	public AdmissionFormFieldDefinition(Guid id, Guid formDefinitionId, Guid sectionId, string code, string label, AdmissionFormFieldType fieldType, AdmissionFormBindingType bindingType, string? bindingKey, bool required, bool readOnly, int displayOrder, string? placeholder, string? helpText, string? defaultValue, string? validationJson, string? visibilityRuleJson) : base(id) { FormDefinitionId = Check.NotDefaultOrNull<Guid>(formDefinitionId, nameof(formDefinitionId)); SectionId = Check.NotDefaultOrNull<Guid>(sectionId, nameof(sectionId)); Code = Check.NotNullOrWhiteSpace(code, nameof(code)).Trim().ToUpperInvariant(); Label = Check.NotNullOrWhiteSpace(label, nameof(label)).Trim(); FieldType = fieldType; BindingType = bindingType; BindingKey = string.IsNullOrWhiteSpace(bindingKey) ? null : bindingKey.Trim(); Required = required; ReadOnly = readOnly; DisplayOrder = displayOrder; Placeholder = placeholder; HelpText = helpText; DefaultValue = defaultValue; ValidationJson = validationJson; VisibilityRuleJson = visibilityRuleJson; }
}
